  "contents": "import * as React from 'react'
import { Minus, Plus, RotateCcw } from 'lucide-react'
import { cn } from '@/shared/lib/utils'
import { Button } from '@/shared/ui/button'
import {
  POSTURE_DIAGRAM_URL,
  VIEW_LABELS,
  type BodyMapPostureView,
} from '@/features/service-users/body-map/catalog/body-map-views'
import type { PlaceMarkerPayload } from '@/features/service-users/body-map/components/BodyMapCanvas'
import { BodyMapMarkerLegend } from '@/features/service-users/body-map/components/BodyMapMarkerLegend'
import { medicationSiteMarkerLabel } from '@/features/service-users/body-map/components/BodyMapMedicationSiteDetail'
import { readMarkerPlacement } from '@/features/service-users/body-map/utils/body-map-coords'
import type { BodyMapRecordRow } from '@/features/service-users/body-map/types'

const MARKER_CLASS_MAP: Record<string, string> = {
  'm-injury': 'bg-red-600',
  'm-wound': 'bg-violet-600',
  'm-pressure': 'bg-orange-600',
  'm-med': 'bg-blue-600',
  'm-patch': 'bg-blue-500',
  'm-injection': 'bg-teal-600 ring-2 ring-teal-200',
  'm-spray': 'bg-cyan-600 ring-2 ring-cyan-200',
  'm-pain': 'bg-pink-600',
  'm-skin': 'bg-yellow-600',
  'm-safeguard': 'bg-red-900 animate-pulse',
}

function markerPinClass(record: BodyMapRecordRow): string {
  if (record.safeguardingTriggered || record.recordType === 'SAFEGUARDING') return 'm-safeguard'
  const typeKey = record.recordType.toLowerCase()
  if (typeKey === 'medication') return 'm-med'
  if (typeKey === 'wound') return 'm-wound'
  if (typeKey === 'pressure') return 'm-pressure'
  if (typeKey === 'pain') return 'm-pain'
  if (typeKey === 'skin') return 'm-skin'
  return 'm-injury'
}

function tailwindForMarkerClass(protoClass: string): string {
  for (const [key, tw] of Object.entries(MARKER_CLASS_MAP)) {
    if (protoClass.includes(key)) return tw
  }
  return 'bg-red-600'
}

function isVisibleOnMap(
  record: BodyMapRecordRow,
  posture: BodyMapPostureView,
  showMeds: boolean,
  showCleared: boolean,
): boolean {
  const marker = record.markers[0]
  if (!marker) return false
  const { canvasView } = readMarkerPlacement(record, marker)
  if (canvasView !== posture) return false
  if (!showMeds && record.recordType === 'MEDICATION') return false
  if (!showCleared && (marker.status === 'CLOSED' || marker.status === 'RESOLVED')) return false
  return true
}

function clickToPercent(clientX: number, clientY: number, host: HTMLElement): { x: number; y: number } | null {
  const svg = host.querySelector('svg')
  if (!svg) return null
  const rect = svg.getBoundingClientRect()
  if (rect.width <= 0 || rect.height <= 0) return null
  const x = Math.min(100, Math.max(0, ((clientX - rect.left) / rect.width) * 100))
  const y = Math.min(100, Math.max(0, ((clientY - rect.top) / rect.height) * 100))
  return { x, y }
}

function MapFilterChip({
  checked,
  onChange,
  label,
}: {
  checked: boolean
  onChange?: (v: boolean) => void
  label: string
}) {
  if (!onChange) return null
  return (
    <button
      type="button"
      className={cn(
        'rounded-full border px-2 py-0.5 text-[10px] font-medium transition-colors',
        checked
          ? 'border-primary bg-primary/10 text-primary'
          : 'border-border text-muted-foreground hover:bg-muted',
      )}
      onClick={() => onChange(!checked)}
    >
      {label}
    </button>
  )
}

type Props = {
  posture: BodyMapPostureView
  records: BodyMapRecordRow[]
  pendingMarker: PlaceMarkerPayload | null
  selectedRecordId: string | null
  markMode: boolean
  showCleared: boolean
  showMeds?: boolean
  onShowClearedChange?: (value: boolean) => void
  onShowMedsChange?: (value: boolean) => void
  onPlaceMarker: (coords: PlaceMarkerPayload) => void
  onSelectRecord: (recordId: string) => void
  className?: string
}

export function BodyMapPostureCanvas({
  posture,
  records,
  pendingMarker,
  selectedRecordId,
  markMode,
  showCleared,
  showMeds = true,
  onShowClearedChange,
  onShowMedsChange,
  onPlaceMarker,
  onSelectRecord,
  className,
}: Props) {
  const [ready, setReady] = React.useState(false)
  const [loadError, setLoadError] = React.useState<string | null>(null)
  const [canvasScale, setCanvasScale] = React.useState(1)
  const [canvasPan, setCanvasPan] = React.useState({ x: 20, y: 20 })

  const svgWrapRef = React.useRef<HTMLDivElement>(null)
  const hostRef = React.useRef<HTMLDivElement>(null)
  const viewportRef = React.useRef<HTMLDivElement>(null)

  React.useEffect(() => {
    let cancelled = false
    const wrap = svgWrapRef.current
    if (!wrap) return

    setReady(false)
    setLoadError(null)

    void fetch(POSTURE_DIAGRAM_URL[posture])
      .then(res => {
        if (!res.ok) throw new Error(`Could not load ${VIEW_LABELS[posture]} diagram`)
        return res.text()
      })
      .then(svgText => {
        if (cancelled) return
        wrap.innerHTML = svgText
        const svg = wrap.querySelector('svg')
        if (svg) {
          svg.setAttribute('width', '100%')
          svg.setAttribute('height', '100%')
          svg.style.maxHeight = '72vh'
          svg.style.display = 'block'
        }
        setReady(true)
      })
      .catch(e => {
        if (!cancelled) {
          setLoadError(e instanceof Error ? e.message : 'Failed to load diagram')
        }
      })

    return () => {
      cancelled = true
    }
  }, [posture])

  React.useEffect(() => {
    const inner = viewportRef.current?.querySelector('#posture-canvas-inner') as HTMLElement | null
    if (inner) {
      inner.style.transform = `translate(${canvasPan.x}px, ${canvasPan.y}px) scale(${canvasScale})`
    }
  }, [canvasPan, canvasScale])

  const handleDiagramClick = (e: React.MouseEvent) => {
    if (!markMode) return
    const host = hostRef.current
    if (!host) return
    if ((e.target as HTMLElement).closest('[data-marker-pin]')) return

    const pt = clickToPercent(e.clientX, e.clientY, host)
    if (!pt) return
    e.stopPropagation()

    onPlaceMarker({
      recordView: posture,
      canvasView: posture,
      x: pt.x,
      y: pt.y,
      bodyPart: 'Marked location',
      side: 'Centre',
      summaryLabel: `${VIEW_LABELS[posture]} — marked location`,
      freeClick: true,
    })
  }

  const markerPins = React.useMemo(() => {
    const pins: {
      key: string
      left: string
      top: string
      label: string
      recordId: string
      protoClass: string
      faded: boolean
      selected: boolean
      number: number
    }[] = []

    const visible = records
      .filter(r => isVisibleOnMap(r, posture, showMeds, showCleared))
      .sort(
        (a, b) =>
          new Date(a.firstNoticedAt ?? a.createdAt).getTime() -
          new Date(b.firstNoticedAt ?? b.createdAt).getTime(),
      )

    let displayIndex = 0
    for (const record of visible) {
      const marker = record.markers[0]!
      displayIndex++
      pins.push({
        key: record.id,
        left: `${marker.xCoordinate}%`,
        top: `${marker.yCoordinate}%`,
        label: medicationSiteMarkerLabel(
          record,
          record.subType ?? record.recordType,
          marker.bodyPart,
        ),
        recordId: record.id,
        protoClass: markerPinClass(record),
        faded: marker.status === 'CLOSED' || marker.status === 'RESOLVED',
        selected: selectedRecordId === record.id,
        number: displayIndex,
      })
    }
    return pins
  }, [records, posture, showCleared, showMeds, selectedRecordId])

  const pendingPinPos =
    pendingMarker && pendingMarker.canvasView === posture
      ? { left: `${pendingMarker.x}%`, top: `${pendingMarker.y}%` }
      : null

  if (loadError) {
    return (
      <div className="rounded-xl border border-destructive/30 bg-destructive/5 p-6 text-sm text-destructive">
        {loadError}
      </div>
    )
  }

  if (!ready) {
    return (
      <div
        className={cn(
          'flex items-center justify-center rounded-xl border border-border bg-card text-sm text-muted-foreground min-h-[320px]',
          className,
        )}
      >
        Loading {VIEW_LABELS[posture]?.toLowerCase() ?? posture} diagram…
      </div>
    )
  }

  return (
    <div
      className={cn(
        'flex min-h-0 flex-col overflow-hidden border border-border bg-card rounded-xl',
        className,
      )}
    >
      <div className="flex flex-wrap items-center gap-1.5 border-b border-border px-2 py-1.5">
        <span className="rounded-full bg-muted px-2 py-0.5 text-[10px] font-medium text-muted-foreground">
          {VIEW_LABELS[posture]}
        </span>
        {markMode ? (
          <span className="hidden rounded-full bg-indigo-100 px-2 py-0.5 text-[10px] font-medium text-indigo-900 sm:inline">
            Tap diagram to place marker
          </span>
        ) : null}
        <div className="flex flex-wrap items-center gap-1 sm:ml-1">
          <MapFilterChip checked={showCleared} onChange={onShowClearedChange} label="Resolved" />
          <MapFilterChip checked={showMeds} onChange={onShowMedsChange} label="Med sites" />
        </div>
        <div className="ml-auto flex items-center gap-0.5">
          <BodyMapMarkerLegend />
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="size-7"
            onClick={() => setCanvasScale(s => Math.max(0.5, s - 0.15))}
          >
            <Minus className="size-3.5" />
          </Button>
          <span className="min-w-9 text-center text-[10px] tabular-nums text-muted-foreground">
            {Math.round(canvasScale * 100)}%
          </span>
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="size-7"
            onClick={() => setCanvasScale(s => Math.min(2.5, s + 0.15))}
          >
            <Plus className="size-3.5" />
          </Button>
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="size-7"
            onClick={() => {
              setCanvasScale(1)
              setCanvasPan({ x: 20, y: 20 })
            }}
          >
            <RotateCcw className="size-3.5" />
          </Button>
        </div>
      </div>

      <div
        ref={viewportRef}
        className={cn(
          'relative min-h-0 flex-1 overflow-auto bg-white',
          markMode && 'cursor-crosshair',
        )}
      >
        <div
          id="posture-canvas-inner"
          className="relative inline-block min-w-full p-4 transition-transform"
          style={{ transformOrigin: 'top left' }}
        >
          <div
            ref={hostRef}
            className="relative mx-auto max-w-2xl"
            onClick={handleDiagramClick}
            role="presentation"
          >
            <div ref={svgWrapRef} className="body-svg-wrap [&_svg]:mx-auto" />
            <div className="pointer-events-none absolute inset-0">
              {markerPins.map(pin => (
                <button
                  key={pin.key}
                  type="button"
                  data-marker-pin
                  title={pin.label}
                  style={{ left: pin.left, top: pin.top }}
                  className={cn(
                    'pointer-events-auto absolute flex h-7 w-7 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full border-2 border-white text-[10px] font-bold text-white shadow-md transition-transform hover:scale-110',
                    tailwindForMarkerClass(pin.protoClass),
                    pin.selected && 'ring-2 ring-indigo-500 ring-offset-2',
                    pin.faded && 'opacity-45',
                  )}
                  onClick={ev => {
                    ev.stopPropagation()
                    onSelectRecord(pin.recordId)
                  }}
                >
                  {pin.number}
                </button>
              ))}
              {pendingPinPos ? (
                <div
                  className="absolute flex h-7 w-7 -translate-x-1/2 -translate-y-1/2 animate-pulse items-center justify-center rounded-full border-2 border-white bg-indigo-600 text-sm font-bold text-white shadow-lg ring-2 ring-indigo-400"
                  style={{ left: pendingPinPos.left, top: pendingPinPos.top }}
                >
                  +
                </div>
              ) : null}
            </div>
          </div>
        </div>
      </div>

      {pendingMarker && pendingMarker.canvasView === posture ? (
        <p className="border-t border-indigo-100 bg-indigo-50/80 px-3 py-2 text-xs text-indigo-900">
          Selected: <strong>{pendingMarker.summaryLabel ?? pendingMarker.bodyPart}</strong>
          {' · '}
          {VIEW_LABELS[posture]} ({pendingMarker.x.toFixed(1)}%, {pendingMarker.y.toFixed(1)}%)
        </p>
      ) : null}
    </div>
  )
}
"
}

