          {mergedOptions.map(o => (
            <SelectItem key={o.id} value={o.id}>
              {o.name}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      {tip ? <FieldTip text={tip} /> : null}
    </div>
  )
}"
