function StaffMini({
  name,
  role,
  tone,
}: {
  name: string
  role: string
  tone: 'teal' | 'blue'
}) {
  const parts = name.split(/\s+/).filter(Boolean)
  const ini = initialsFromName(parts[0], parts[1])
  return (
    <div className="mb-1.5 flex items-center gap-2">
      <div
        className={cn(
          'flex h-9 w-9 items-center justify-center rounded-full text-xs font-semibold',
          tone === 'teal' && 'bg-teal-100 text-teal-800',
          tone === 'blue' && 'bg-blue-100 text-blue-800',
        )}
      >
        {ini}
      </div>
      <div>
        <div className="text-xs font-medium leading-tight">{name}</div>
        <div className="text-[11px] text-muted-foreground">{role}</div>
      </div>
    </div>
  )
}

function ModuleTile({
  title,
  sub,
  icon,
  iconBg,
  to,
  search,
  serviceUserId,
  badge,
  badgeTone = 'red',
  disabled,
}: {
  title: string
  sub: string
  icon: React.ReactNode
  iconBg: string
  to?: string
  search?: Record<string, string>
  serviceUserId?: string
  badge?: string
  badgeTone?: 'red' | 'amber' | 'blue'
  disabled?: boolean
}) {
  const inner = (
    <>
      {badge ? (
        <span
          className={cn(
            'absolute right-2.5 top-2.5 min-w-[18px] rounded-full px-1.5 py-0.5 text-center text-[10px] font-bold text-white',
            badgeTone === 'amber' && 'bg-amber-500',
            badgeTone === 'blue' && 'bg-blue-500',
            badgeTone === 'red' && 'bg-red-500',
          )}
        >
          {badge}
        </span>
      ) : null}
      {disabled ? (
        <span className="absolute right-2.5 top-2.5 rounded-full bg-slate-100 px-1.5 py-0.5 text-[10px] text-muted-foreground">
          Soon
        </span>
      ) : null}
      <div className={cn('mb-1 flex h-9 w-9 items-center justify-center rounded-md', iconBg)}>{icon}</div>
      <div className="text-[13px] font-semibold text-slate-900 dark:text-foreground">{title}</div>
      <div className="text-[11px] leading-snug text-muted-foreground">{sub}</div>
    </>
  )
  const className = cn(
    'relative flex flex-col items-start rounded-[14px] border border-slate-200 bg-white p-3.5 transition-all dark:border-border dark:bg-card',
    disabled ? 'cursor-default opacity-55' : 'hover:border-teal-600 hover:shadow-md',
  )
  if (disabled || !to || !serviceUserId) {
    return <div className={className}>{inner}</div>
  }
  return (
    <Link
      to={to}
      params={{ serviceUserId }}
      search={search}
      className={className}
    >
      {inner}
    </Link>
  )
}
"
