/** Raw NHS Website Content API (schema.org-style) — fields vary by page. */
export type NhsWebPageJson = {
  '@type'?: string | string[];
  name?: string;
  headline?: string;
  description?: string;
  abstract?: string;
  url?: string;
  text?: string;
  articleBody?: string;
  hasPart?: NhsWebPageJson[];
