  "path": "d:\New folder\Care\careadmin-backend\src\nhs-website-content\nhs-medicine.util.ts",
  "contents": "import type { NhsMedicineInfo, NhsMedicineSearchHit, NhsWebPageJson } from './nhs-medicine.types';

const SLUG_RE = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

export function normalizeMedicineSlug(raw: string): string {
  return raw
    .trim()
    .toLowerCase()
    .replace(/\s+/g, '-')
    .replace(/[^a-z0-9-]/g, '')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
}

export function isValidMedicineSlug(slug: string): boolean {
  return slug.length >= 2 && SLUG_RE.test(slug);
}

export function medicineSlugFromUrl(url: string | undefined): string | undefined {
  if (!url) return undefined;
  const match = url.match(/\/medicines\/([a-z0-9-]+)\/?/i);
  return match?.[1]?.toLowerCase();
}

function stripHtml(text: string): string {
  return text
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function partText(part: NhsWebPageJson): string | undefined {
  const raw =
    (typeof part.text === 'string' && part.text) ||
    (typeof part.articleBody === 'string' && part.articleBody) ||
    (typeof part.description === 'string' && part.description) ||
    undefined;
  return raw ? stripHtml(raw) : undefined;
}

function partName(part: NhsWebPageJson): string {
  return (typeof part.name === 'string' && part.name) || '';
}

function findModuleText(parts: NhsWebPageJson[], patterns: RegExp[]): string | undefined {
  for (const part of parts) {
    const name = partName(part);
    if (!patterns.some(p => p.test(name))) continue;
    const text = partText(part);
    if (text) return truncate(text, 1200);
  }
  return undefined;
}

function truncate(text: string, max: number): string {
  if (text.length <= max) return text;
  return `${text.slice(0, max - 1)}…`;
}

function collectParts(page: NhsWebPageJson): NhsWebPageJson[] {
  const parts: NhsWebPageJson[] = [];
  const push = (items: unknown) => {
    if (Array.isArray(items)) {
      for (const item of items) {
        if (item && typeof item === 'object') parts.push(item as NhsWebPageJson);
      }
    } else if (items && typeof items === 'object') {
      parts.push(items as NhsWebPageJson);
    }
  };
  push(page.hasPart);
  push(page.mainEntityOfPage?.hasPart);
  push(page.itemListElement);
  return parts;
}

export function mapNhsMedicinePage(slug: string, page: NhsWebPageJson): NhsMedicineInfo {
  const parts = collectParts(page);
  const title =
    (typeof page.name === 'string' && page.name) ||
    (typeof page.headline === 'string' && page.headline) ||
    slug;

  const description =
    (typeof page.description === 'string' && stripHtml(page.description)) ||
    (typeof page.abstract === 'string' && stripHtml(page.abstract)) ||
    findModuleText(parts, [/about/i, /key facts/i, /overview/i]) ||
    partText(parts[0]);

  const usedFor =
    findModuleText(parts, [
      /^uses?\b/i,
      /what.*(used|for)/i,
      /who can.*take/i,
      /about\b/i,
    ]) || description;

  const howItWorks = findModuleText(parts, [/how it works/i, /how.*works/i]);

  const medicineType =
    findModuleText(parts, [/key facts/i, /type of medicine/i, /belongs to/i])?.slice(0, 280) ||
    inferTypeFromText(`${title} ${description ?? ''}`);

  const sideEffects = findModuleText(parts, [/side effects/i, /common side effects/i]);

  const warnings = findModuleText(parts, [
    /cautions/i,
    /warnings/i,
    /interactions/i,
    /before taking/i,
    /pregnancy/i,
  ]);

  const sourceUrl =
    (typeof page.url === 'string' && page.url) ||
    `https://www.nhs.uk/medicines/${slug}/`;

  return {
    slug,
    title: stripHtml(title),
    description: description ? truncate(description, 500) : undefined,
    usedFor: usedFor ? truncate(usedFor, 800) : undefined,
    howItWorks,
    medicineType,
    sideEffects,
    warnings,
    sourceUrl,
  };
}

function inferTypeFromText(blob: string): string | undefined {
  const lower = blob.toLowerCase();
  if (/\b(tablets?|caplets?)\b/.test(lower)) return 'Tablet';
  if (/\bcapsules?\b/.test(lower)) return 'Capsule';
  if (/\b(liquid|syrup|solution|suspension)\b/.test(lower)) return 'Liquid';
  if (/\bcream\b/.test(lower)) return 'Cream';
  if (/\bointment\b/.test(lower)) return 'Ointment';
  if (/\bpatch(es)?\b/.test(lower)) return 'Patch';
  if (/\binjection\b/.test(lower)) return 'Injection';
  if (/\binhaler\b/.test(lower)) return 'Inhaler';
  if (/\bdrops\b/.test(lower)) return 'Drops';
  return undefined;
}

export function mapNhsMedicineSearchHits(page: NhsWebPageJson, query: string, limit: number): NhsMedicineSearchHit[] {
  const q = query.trim().toLowerCase();
  const parts = collectParts(page);
  const hits: NhsMedicineSearchHit[] = [];
  const seen = new Set<string>();

  for (const part of parts) {
    const slug = medicineSlugFromUrl(typeof part.url === 'string' ? part.url : undefined);
    const title = typeof part.name === 'string' ? stripHtml(part.name) : '';
    if (!slug || !title) continue;
    if (q.length >= 2 && !slug.includes(q) && !title.toLowerCase().includes(q)) continue;
    if (seen.has(slug)) continue;
    seen.add(slug);
    hits.push({
      slug,
      title,
      description:
        typeof part.description === 'string' ? truncate(stripHtml(part.description), 160) : undefined,
    });
    if (hits.length >= limit) break;
  }

  return hits;
}
"
}

