  "contents": "import {
  BadGatewayException,
  BadRequestException,
  Injectable,
  NotFoundException,
  ServiceUnavailableException,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import type { NhsMedicineInfo, NhsMedicineSearchHit, NhsWebPageJson } from './nhs-medicine.types';
import {
  isValidMedicineSlug,
  mapNhsMedicinePage,
  mapNhsMedicineSearchHits,
  normalizeMedicineSlug,
} from './nhs-medicine.util';

type NhsErrorBody = {
  error?: string;
  message?: string;
  issue?: Array<{ diagnostics?: string }>;
};

@Injectable()
export class NhsMedicineService {
  constructor(private readonly config: ConfigService) {}

  private baseUrl(): string {
    return this.config.get<string>('nhsWebsiteContent.baseUrl', '').replace(/\/$/, '');
  }

  private buildHeaders(): HeadersInit {
    const headers: Record<string, string> = {
      Accept: 'application/json',
    };
    const apiKey = this.config.get<string>('nhsWebsiteContent.apiKey', '').trim();
    const useProduction = this.config.get<boolean>('nhsWebsiteContent.useProduction', false);
    if (useProduction && apiKey) {
      headers.apikey = apiKey;
    }
    return headers;
  }

  /**
   * Fetch UK medicine information from NHS Website Content API (sandbox or production).
   */
  async getNhsMedicineInfo(medicineSlug: string, modules = true): Promise<NhsMedicineInfo> {
    const slug = normalizeMedicineSlug(medicineSlug);
    if (!isValidMedicineSlug(slug)) {
      throw new BadRequestException('Invalid medicine slug. Use lowercase names like paracetamol.');
    }

    const path = `/medicines/${encodeURIComponent(slug)}/`;
    const page = await this.fetchJson(path, modules ? { modules: 'true' } : undefined);

    if (!page || (typeof page === 'object' && Object.keys(page as object).length === 0)) {
      throw new NotFoundException(`No NHS medicine page found for "${slug}".`);
    }

    return mapNhsMedicinePage(slug, page as NhsWebPageJson);
  }

  async searchMedicines(query: string, limit = 8): Promise<NhsMedicineSearchHit[]> {
    const q = query.trim().toLowerCase();
    if (q.length < 2) return [];

    const letter = q[0];
    if (!/^[a-z]$/.test(letter)) {
      throw new BadRequestException('Search must start with a letter (a–z).');
    }

    const listPage = await this.fetchJson('/medicines', { category: letter });
    const hits = mapNhsMedicineSearchHits(listPage as NhsWebPageJson, q, limit);

    if (hits.length > 0) return hits;

    // Direct slug guess (e.g. user typed full slug "paracetamol")
    const directSlug = normalizeMedicineSlug(q);
    if (isValidMedicineSlug(directSlug)) {
      try {
        const info = await this.getNhsMedicineInfo(directSlug);
        return [
          {
            slug: info.slug,
            title: info.title,
            description: info.description,
          },
        ];
      } catch (err) {
        if (err instanceof NotFoundException) return [];
        throw err;
      }
    }

    return [];
  }

  private async fetchJson(
    path: string,
    query?: Record<string, string>,
  ): Promise<unknown> {
    const base = this.baseUrl();
    if (!base) {
      throw new ServiceUnavailableException('NHS Website Content API base URL is not configured.');
    }

    const url = new URL(`${base}${path.startsWith('/') ? path : `/${path}`}`);
    if (query) {
      for (const [key, value] of Object.entries(query)) {
        url.searchParams.set(key, value);
      }
    }

    let res: Response;
    try {
      res = await fetch(url.toString(), {
        method: 'GET',
        headers: this.buildHeaders(),
        signal: AbortSignal.timeout(15_000),
      });
    } catch {
      throw new BadGatewayException(
        'Unable to reach the NHS Website Content API. Check your network and try again.',
      );
    }

    const contentType = res.headers.get('content-type') ?? '';
    const bodyText = await res.text();

    if (!contentType.includes('application/json')) {
      if (res.status === 503 || res.status === 502) {
        throw new ServiceUnavailableException(
          'NHS sandbox is temporarily unavailable. Try again shortly or switch to production with NHS_API_KEY.',
        );
      }
      throw new BadGatewayException(
        'NHS API returned an unexpected response. Ensure you are using the JSON API endpoint.',
      );
    }

    let body: unknown;
    try {
      body = bodyText ? JSON.parse(bodyText) : null;
    } catch {
      throw new BadGatewayException('NHS API returned invalid JSON.');
    }

    if (res.status === 404) {
      throw new NotFoundException('Medicine not found on NHS.uk.');
    }

    if (!res.ok) {
      const err = body as NhsErrorBody | null;
      const detail =
        err?.message ||
        err?.error ||
        err?.issue?.[0]?.diagnostics ||
        `NHS API returned HTTP ${res.status}`;
      if (res.status === 401 || res.status === 403) {
        throw new ServiceUnavailableException(
          'NHS API key is missing or invalid. Set NHS_API_KEY for production.',
        );
      }
      throw new BadGatewayException(detail);
    }

    if (body == null || (typeof body === 'object' && Object.keys(body as object).length === 0)) {
      throw new NotFoundException('Empty response from NHS API.');
    }

    return body;
  }
}
"
}

