import { AnyPermission } from '../common/decorators/permissions.decorator';
import { ApiMedicationStandardResponses } from '../common/decorators/api-standard-responses.decorator';
import { NhsMedicineService } from './nhs-medicine.service';
import {
  NhsMedicineInfoResponseDto,
  NhsMedicineSearchQueryDto,
  NhsMedicineSearchResponseDto,
  NhsMedicineSlugParamDto,
} from './dto/nhs-medicine.dto';

@ApiTags('NHS Website Content')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard, PermissionsGuard)
@Controller('nhs-website-content')
export class NhsMedicineController {
  constructor(private readonly nhsMedicine: NhsMedicineService) {}

  @Get('medicines/search')
  @AnyPermission('service_users.medications.lookups.read', 'service_users.read')
  @ApiOperation({ summary: 'Search medicines A–Z (NHS sandbox / production)' })
  @ApiOkResponse({ type: NhsMedicineSearchResponseDto })
  @ApiMedicationStandardResponses()
  async search(@Query() query: NhsMedicineSearchQueryDto) {
    const data = await this.nhsMedicine.searchMedicines(query.q, query.limit ?? 8);
    return {
      data,
      message: data.length ? 'Medicines found' : 'No matching medicines',
    };
  }

  @Get('medicines/:slug')
  @AnyPermission('service_users.medications.lookups.read', 'service_users.read')
  @ApiOperation({ summary: 'Get NHS.uk medicine page (modules=true)' })
  @ApiOkResponse({ type: NhsMedicineInfoResponseDto })
  @ApiMedicationStandardResponses()
  async getOne(@Param() params: NhsMedicineSlugParamDto) {
    const data = await this.nhsMedicine.getNhsMedicineInfo(params.slug, true);
    return { data, message: 'NHS medicine loaded' };
  }
}
