  "contents": "import { apiJson, type ApiEnvelope } from '@/shared/api/api-client'

/** Normalised NHS.uk medicine information for UI and medication autofill. */
export type NhsMedicineInfo = {
  slug: string
  title: string
  description?: string
  usedFor?: string
  howItWorks?: string
  medicineType?: string
  sideEffects?: string
  warnings?: string
  sourceUrl?: string
}

export type NhsMedicineSearchHit = {
  slug: string
  title: string
  description?: string
}

/**
 * Load medicine details from NHS Website Content API (via CareAdmin backend proxy).
 * Sandbox example slug: paracetamol, ibuprofen, amoxicillin, cetirizine
 */
export async function getNhsMedicineInfo(medicineSlug: string): Promise<NhsMedicineInfo> {
  const slug = medicineSlug.trim().toLowerCase()
  const res = await apiJson<ApiEnvelope<NhsMedicineInfo>>(
    `/nhs-website-content/medicines/${encodeURIComponent(slug)}`,
    { method: 'GET' },
  )
  return res.data
}

export async function searchNhsMedicines(q: string, limit = 8): Promise<NhsMedicineSearchHit[]> {
  const params = new URLSearchParams({ q: q.trim(), limit: String(limit) })
  const res = await apiJson<ApiEnvelope<NhsMedicineSearchHit[]>>(
    `/nhs-website-content/medicines/search?${params}`,
    { method: 'GET' },
  )
  return res.data
}
"
}

