  "contents": "import type { MedicationLookupsBundle } from '@/features/service-users/api/service-users.api'
import type { NhsMedicineInfo, NhsMedicineSearchHit } from '@/features/service-users/api/nhs-medicine.api'

export type MedicationNhsAutofill = {
  medicationName: string
  reasonForMedication?: string
  medicationTypeId?: string
}

const TYPE_NAME_TO_CODE: Record<string, string> = {
  tablet: 'TABLET',
  capsules: 'CAPSULE',
  capsule: 'CAPSULE',
  liquid: 'LIQUID',
  cream: 'CREAM',
  ointment: 'OINTMENT',
  patch: 'PATCH',
  injection: 'INJECTION',
  inhaler: 'INHALER',
  drops: 'DROPS',
  spray: 'SPRAY',
}

function lookupIdByTypeName(
  lookups: MedicationLookupsBundle | undefined,
  typeName: string | undefined,
): string | undefined {
  if (!typeName?.trim() || !lookups?.types?.length) return undefined
  const lower = typeName.toLowerCase()
  const code = TYPE_NAME_TO_CODE[lower] ?? Object.entries(TYPE_NAME_TO_CODE).find(([k]) => lower.includes(k))?.[1]
  if (code) {
    return lookups.types.find(t => t.code === code)?.id
  }
  return lookups.types.find(t => t.name.toLowerCase() === lower)?.id
}

function buildReason(info: NhsMedicineInfo): string | undefined {
  if (info.usedFor?.trim()) return info.usedFor.trim()
  if (info.description?.trim()) return info.description.trim()
  return undefined
}

export function nhsMedicineToAutofill(
  info: NhsMedicineInfo,
  lookups: MedicationLookupsBundle | undefined,
): MedicationNhsAutofill {
  return {
    medicationName: info.title,
    reasonForMedication: buildReason(info),
    medicationTypeId: lookupIdByTypeName(lookups, info.medicineType),
  }
}

export function nhsSearchHitToAutofill(
  hit: NhsMedicineSearchHit,
  info: NhsMedicineInfo,
  lookups: MedicationLookupsBundle | undefined,
): MedicationNhsAutofill {
  return nhsMedicineToAutofill(
    { ...info, title: hit.title || info.title },
    lookups,
  )
}
"
}

