  "contents": "import * as React from 'react'
import { useQuery } from '@tanstack/react-query'
import { ExternalLink, Loader2, Search } from 'lucide-react'
import { ApiError } from '@/shared/api/api-client'
import { getNhsMedicineInfo } from '@/features/service-users/api/nhs-medicine.api'
import { Button } from '@/shared/ui/button'
import { Input } from '@/shared/ui/input'

const EXAMPLE_SLUGS = ['paracetamol', 'ibuprofen', 'amoxicillin', 'cetirizine', 'acrivastine'] as const

function InfoBlock({ label, children }: { label: string; children: React.ReactNode }) {
  if (!children) return null
  return (
    <div className="rounded-lg border border-border bg-card p-4">
      <h3 className="mb-2 text-sm font-semibold text-foreground">{label}</h3>
      <p className="whitespace-pre-wrap text-sm leading-relaxed text-muted-foreground">{children}</p>
    </div>
  )
}

/** Example page: search NHS.uk medicine by slug and display normalised fields. */
export default function NhsMedicineLookupPage() {
  const [slugInput, setSlugInput] = React.useState('paracetamol')
  const [activeSlug, setActiveSlug] = React.useState('paracetamol')

  const query = useQuery({
    queryKey: ['nhs', 'medicine', activeSlug] as const,
    queryFn: () => getNhsMedicineInfo(activeSlug),
    enabled: activeSlug.trim().length >= 2,
    retry: false,
  })

  const error =
    query.error instanceof ApiError
      ? query.error.message
      : query.error
        ? 'Failed to load medicine'
        : null

  function runSearch(slug?: string) {
    const next = (slug ?? slugInput).trim().toLowerCase()
    if (next.length < 2) return
    setSlugInput(next)
    setActiveSlug(next)
  }

  const info = query.data

  return (
    <div className="mx-auto max-w-3xl space-y-6 p-6">
      <div>
        <h1 className="text-2xl font-semibold text-foreground">NHS medicine lookup</h1>
        <p className="mt-1 text-sm text-muted-foreground">
          Sandbox API (no key):{' '}
          <code className="rounded bg-muted px-1 py-0.5 text-xs">
            sandbox.api.service.nhs.uk/nhs-website-content/medicines/&#123;slug&#125;/?modules=true
          </code>
        </p>
        <p className="mt-2 text-xs text-muted-foreground">
          Production: set <code className="rounded bg-muted px-1">NHS_WEBSITE_CONTENT_USE_PRODUCTION=true</code>{' '}
          and <code className="rounded bg-muted px-1">NHS_API_KEY</code> on the backend with header{' '}
          <code className="rounded bg-muted px-1">apikey</code>.
        </p>
      </div>

      <form
        className="flex flex-wrap items-end gap-3"
        onSubmit={e => {
          e.preventDefault()
          runSearch()
        }}
      >
        <div className="min-w-[14rem] flex-1 space-y-1">
          <label className="text-sm font-medium" htmlFor="nhs-medicine-slug">
            Medicine slug
          </label>
          <Input
            id="nhs-medicine-slug"
            value={slugInput}
            onChange={e => setSlugInput(e.target.value)}
            placeholder="e.g. paracetamol"
          />
        </div>
        <Button type="submit" disabled={query.isFetching}>
          {query.isFetching ? (
            <Loader2 className="mr-2 h-4 w-4 animate-spin" />
          ) : (
            <Search className="mr-2 h-4 w-4" />
          )}
          Look up
        </Button>
      </form>

      <div className="flex flex-wrap gap-2">
        {EXAMPLE_SLUGS.map(slug => (
          <Button key={slug} type="button" variant="outline" size="sm" onClick={() => runSearch(slug)}>
            {slug}
          </Button>
        ))}
      </div>

      {error && (
        <p className="rounded-md border border-destructive/30 bg-destructive/10 px-4 py-3 text-sm text-destructive" role="alert">
          {error}
        </p>
      )}

      {query.isFetching && !info && (
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <Loader2 className="h-4 w-4 animate-spin" />
          Loading from NHS…
        </div>
      )}

      {info && (
        <div className="space-y-4">
          <div className="flex flex-wrap items-start justify-between gap-2">
            <div>
              <h2 className="text-xl font-semibold">{info.title}</h2>
              <p className="text-sm text-muted-foreground">Slug: {info.slug}</p>
            </div>
            {info.sourceUrl ? (
              <a
                href={info.sourceUrl}
                target="_blank"
                rel="noreferrer"
                className="inline-flex items-center gap-1 text-sm font-medium text-teal-700 hover:underline"
              >
                View on NHS.uk
                <ExternalLink className="h-3.5 w-3.5" />
              </a>
            ) : null}
          </div>

          <InfoBlock label="Description">{info.description}</InfoBlock>
          <InfoBlock label="What it is used for">{info.usedFor}</InfoBlock>
          <InfoBlock label="How it works">{info.howItWorks}</InfoBlock>
          <InfoBlock label="Medicine type">{info.medicineType}</InfoBlock>
          <InfoBlock label="Side effects">{info.sideEffects}</InfoBlock>
          <InfoBlock label="Warnings / interactions">{info.warnings}</InfoBlock>
        </div>
      )}
    </div>
  )
}
"
}

