  "contents": "import * as React from 'react'
import $ from 'jquery'
import 'summernote/dist/summernote-lite.min.css'
import 'summernote/dist/summernote-lite.min.js'
import { cn } from '@/shared/lib/utils'

if (typeof window !== 'undefined') {
  window.jQuery = $
  window.$ = $
}

interface SummernoteEditorProps {
  value?: string
  onChange?: (html: string) => void
  placeholder?: string
  disabled?: boolean
  minHeight?: number
  className?: string
}

export function SummernoteEditor({
  value = '',
  onChange,
  placeholder = 'Start typing…',
  disabled = false,
  minHeight = 160,
  className,
}: SummernoteEditorProps) {
  const hostRef = React.useRef<HTMLDivElement>(null)
  const onChangeRef = React.useRef(onChange)
  onChangeRef.current = onChange
  const mountedRef = React.useRef(false)

  React.useEffect(() => {
    const el = hostRef.current
    if (!el || mountedRef.current) return
    mountedRef.current = true

    const $el = $(el)
    $el.summernote({
      placeholder,
      height: minHeight,
      disableDragAndDrop: true,
      toolbar: [
        ['style', ['style']],
        ['font', ['bold', 'italic', 'underline', 'clear']],
        ['para', ['ul', 'ol', 'paragraph']],
        ['insert', ['link']],
        ['view', ['fullscreen', 'codeview', 'help']],
      ],
      callbacks: {
        onChange: (contents: string) => {
          onChangeRef.current?.(contents)
        },
      },
    })
    if (value) {
      $el.summernote('code', value)
    }
    if (disabled) {
      $el.summernote('disable')
    }

    return () => {
      $el.summernote('destroy')
      mountedRef.current = false
    }
  }, [disabled, minHeight, placeholder])

  React.useEffect(() => {
    const el = hostRef.current
    if (!el || !mountedRef.current) return
    const $el = $(el)
    const current = $el.summernote('code') as string
    if ((value ?? '') !== current) {
      $el.summernote('code', value ?? '')
    }
  }, [value])

  React.useEffect(() => {
    const el = hostRef.current
    if (!el || !mountedRef.current) return
    $(el).summernote(disabled ? 'disable' : 'enable')
  }, [disabled])

  return (
    <div
      className={cn(
        'summernote-editor-host rounded-md border border-input bg-background [&_.note-editor]:mb-0',
        disabled && 'pointer-events-none opacity-60',
        className,
      )}
    >
      <div ref={hostRef} />
    </div>
  )
}

export function looksLikeHtmlContent(text: string | null | undefined): boolean {
  if (!text?.trim()) return false
  return /<[a-z][\s\S]*>/i.test(text.trim())
}
"
