  "contents": "import type { BodyMapPostureView } from '@/features/service-users/body-map/catalog/body-map-views'

/** Click target on leaning/sitting SVG (% of viewBox) — aligned to pink markers on reference SVGs */
export type PostureHotspot = {
  bodyPart: string
  x: number
  y: number
  /** Hit radius in viewBox-x units (% width); y is scaled by aspect ratio for round hits on screen */
  radius?: number
}

/** Leaning diagram — centres from assets/figma/body-map/leaning.svg (#ff0087 markers) */
export const LEANING_POSTURE_HOTSPOTS: PostureHotspot[] = [
  { bodyPart: 'Ear', x: 27.3, y: 15.4, radius: 6 },
  { bodyPart: 'Shoulder', x: 39.7, y: 16.5, radius: 6 },
  { bodyPart: 'Elbow', x: 14.7, y: 48.0, radius: 7 },
  { bodyPart: 'Hip', x: 44.6, y: 54.1, radius: 7 },
  { bodyPart: 'Thigh', x: 66.0, y: 47.5, radius: 7 },
  { bodyPart: 'Inner side of the knee', x: 21.9, y: 51.0, radius: 6 },
  { bodyPart: 'Leg', x: 26.1, y: 53.7, radius: 6 },
  { bodyPart: 'Heel', x: 85.9, y: 53.6, radius: 6 },
]

/** Sitting diagram — centres from assets/figma/body-map/sitting.svg (cls-7 markers) */
export const SITTING_POSTURE_HOTSPOTS: PostureHotspot[] = [
  { bodyPart: 'Middle of spine', x: 40.6, y: 38.2, radius: 7 },
  { bodyPart: 'Base of spine', x: 42.0, y: 58.4, radius: 7 },
  { bodyPart: 'Buttocks', x: 41.8, y: 53.5, radius: 7 },
  { bodyPart: 'Back of knees', x: 70.5, y: 81.4, radius: 6 },
  { bodyPart: 'Heels', x: 63.5, y: 81.4, radius: 6 },
  { bodyPart: 'Balls of feet', x: 58.0, y: 88.0, radius: 6 },
]

const HOTSPOTS_BY_POSTURE: Record<BodyMapPostureView, PostureHotspot[]> = {
  leaning: LEANING_POSTURE_HOTSPOTS,
  sitting: SITTING_POSTURE_HOTSPOTS,
}

export const POSTURE_VIEWBOX_ASPECT: Record<BodyMapPostureView, number> = {
  leaning: 375 / 416.875,
  sitting: 374.625 / 270,
}

export function postureHotspotsFor(view: BodyMapPostureView): PostureHotspot[] {
  return HOTSPOTS_BY_POSTURE[view]
}

export function resolvePostureHotspot(
  view: BodyMapPostureView,
  x: number,
  y: number,
  aspectRatio = POSTURE_VIEWBOX_ASPECT[view],
): PostureHotspot | null {
  const spots = postureHotspotsFor(view)
  let best: PostureHotspot | null = null
  let bestDist = Infinity
  for (const spot of spots) {
    const r = spot.radius ?? 7
    const dx = (x - spot.x) * aspectRatio
    const dy = y - spot.y
    const dist = Math.hypot(dx, dy)
    if (dist <= r && dist < bestDist) {
      best = spot
      bestDist = dist
    }
  }
  return best
}
"
}

