    const dy = y - spot.y
    const dist = Math.hypot(dx, dy)
    const threshold = (spot.radius ?? 7) + snapRadius
    if (dist <= threshold && dist < nearestDist) {
      nearest = spot
      nearestDist = dist
    }
  }

  return nearest
}
