  "path": "d:\New folder\Care\care-admin\src\shared\lib\parse-google-place.ts",
  "contents": "import type { GoogleAddressComponent, GooglePlaceResult } from '@/shared/lib/google-maps'

export type ParsedPostalAddress = {
  addressLine1: string
  addressLine2: string
  town: string
  county: string
  country: string
  postcode: string
  latitude: number | null
  longitude: number | null
  formattedAddress: string
}

function component(components: GoogleAddressComponent[], type: string): GoogleAddressComponent | undefined {
  return components.find((c) => c.types.includes(type))
}

function componentName(components: GoogleAddressComponent[], type: string, useShort = false): string {
  const c = component(components, type)
  if (!c) return ''
  return (useShort ? c.short_name : c.long_name)?.trim() ?? ''
}

/** Map Google Places / Geocoder components to CareAdmin address fields. */
export function parseGoogleAddressComponents(
  place: Pick<GooglePlaceResult, 'address_components' | 'formatted_address' | 'geometry'>,
): ParsedPostalAddress {
  const parts = place.address_components ?? []
  const streetNumber = componentName(parts, 'street_number')
  const route = componentName(parts, 'route')
  const subpremise = componentName(parts, 'subpremise')
  const premise = componentName(parts, 'premise')

  let addressLine1 = [streetNumber, route].filter(Boolean).join(' ').trim()
  if (!addressLine1 && premise) addressLine1 = premise

  const addressLine2 = subpremise || (premise && addressLine1 !== premise ? premise : '')

  const town =
    componentName(parts, 'postal_town') ||
    componentName(parts, 'locality') ||
    componentName(parts, 'sublocality') ||
    componentName(parts, 'administrative_area_level_2')

  const county =
    componentName(parts, 'administrative_area_level_2') ||
    componentName(parts, 'administrative_area_level_1')

  const country = componentName(parts, 'country')
  const postcode = componentName(parts, 'postal_code')

  const lat = place.geometry?.location?.lat?.()
  const lng = place.geometry?.location?.lng?.()

  return {
    addressLine1,
    addressLine2,
    town,
    county,
    country,
    postcode,
    latitude: typeof lat === 'number' && Number.isFinite(lat) ? lat : null,
    longitude: typeof lng === 'number' && Number.isFinite(lng) ? lng : null,
    formattedAddress: place.formatted_address?.trim() ?? addressLine1,
  }
}

export function formatAddressLines(value: {
  addressLine1?: string
  addressLine2?: string
  town?: string
  county?: string
  country?: string
  postcode?: string
}): string {
  return [
    value.addressLine1,
    value.addressLine2,
    value.town,
    value.county,
    value.postcode,
    value.country,
  ]
    .map((s) => s?.trim())
    .filter(Boolean)
    .join(', ')
}
"
}

{
  "path": "d:\New folder\Care\care-admin\src\shared\ui\address-places-field.tsx",
  "contents": "import * as React from 'react'
import { Loader2, MapPin, Search } from 'lucide-react'
import { cn } from '@/shared/lib/utils'
import { Input } from '@/shared/ui/input'
import { Button } from '@/shared/ui/button'
import { Label } from '@/shared/ui/form-field'
import { MapView, type MapLocation } from '@/shared/ui/map'
import {
  getGoogleMapsApiKey,
  isGoogleMapsConfigured,
  loadGoogleMaps,
  type GooglePlaceResult,
} from '@/shared/lib/google-maps'
import { formatAddressLines, parseGoogleAddressComponents } from '@/shared/lib/parse-google-place'

export type AddressPlacesValue = {
  addressLine1: string
  addressLine2: string
  town: string
  county: string
  country: string
  postcode: string
  latitude: string
  longitude: string
}

type Props = {
  value: AddressPlacesValue
  onChange: (patch: Partial<AddressPlacesValue>) => void
  disabled?: boolean
  /** Restrict Places suggestions (ISO 3166-1 alpha-2). Default: gb */
  countryRestriction?: string | string[]
  className?: string
  /** Extra fields below address (key safe, access instructions, etc.) */
  children?: React.ReactNode
}

function coordsFromValue(value: AddressPlacesValue): { lat: number; lng: number } | null {
  const lat = Number(value.latitude)
  const lng = Number(value.longitude)
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null
  return { lat, lng }
}

export function AddressPlacesField({
  value,
  onChange,
  disabled,
  countryRestriction = 'gb',
  className,
  children,
}: Props) {
  const searchRef = React.useRef<HTMLInputElement>(null)
  const autocompleteRef = React.useRef<{ addListener: (event: string, handler: () => void) => void } | null>(null)
  const [searchText, setSearchText] = React.useState('')
  const [mapsReady, setMapsReady] = React.useState(false)
  const [mapsError, setMapsError] = React.useState<string | null>(null)
  const [geocoding, setGeocoding] = React.useState(false)
  const [showMap, setShowMap] = React.useState(false)
  const configured = isGoogleMapsConfigured()

  const applyParsed = React.useCallback(
    (parsed: ReturnType<typeof parseGoogleAddressComponents>) => {
      onChange({
        addressLine1: parsed.addressLine1,
        addressLine2: parsed.addressLine2,
        town: parsed.town,
        county: parsed.county,
        country: parsed.country,
        postcode: parsed.postcode,
        latitude: parsed.latitude != null ? String(parsed.latitude) : '',
        longitude: parsed.longitude != null ? String(parsed.longitude) : '',
      })
      if (parsed.latitude != null && parsed.longitude != null) {
        setShowMap(true)
      }
    },
    [onChange],
  )

  const onPlaceSelected = React.useCallback(() => {
    const ac = autocompleteRef.current as { getPlace?: () => GooglePlaceResult } | null
    const place = ac?.getPlace?.()
    if (!place?.address_components?.length) return
    const parsed = parseGoogleAddressComponents(place)
    applyParsed(parsed)
    setSearchText(parsed.formattedAddress || formatAddressLines(parsed))
  }, [applyParsed])

  React.useEffect(() => {
    if (!configured || disabled) return
    let cancelled = false

    void loadGoogleMaps()
      .then((google) => {
        if (cancelled || !searchRef.current) return
        const Autocomplete = google.maps.places.Autocomplete
        const ac = new Autocomplete(searchRef.current, {
          fields: ['address_components', 'geometry', 'formatted_address'],
          types: ['address'],
          componentRestrictions: { country: countryRestriction },
        })
        autocompleteRef.current = ac
        ac.addListener('place_changed', onPlaceSelected)
        setMapsReady(true)
        setMapsError(null)
      })
      .catch((e: unknown) => {
        if (!cancelled) {
          setMapsError(e instanceof Error ? e.message : 'Could not load Google Maps')
        }
      })

    return () => {
      cancelled = true
    }
  }, [configured, disabled, countryRestriction, onPlaceSelected])

  const geocodeCurrentAddress = async () => {
    const query = formatAddressLines(value)
    if (!query.trim()) return
    setGeocoding(true)
    setMapsError(null)
    try {
      const google = await loadGoogleMaps()
      const geocoder = new google.maps.Geocoder()
      await new Promise<void>((resolve, reject) => {
        geocoder.geocode({ address: query }, (results, status) => {
          if (status !== 'OK' || !results?.[0]) {
            reject(new Error('Could not find that address on the map'))
            return
          }
          applyParsed(parseGoogleAddressComponents(results[0]))
          resolve()
        })
      })
    } catch (e) {
      setMapsError(e instanceof Error ? e.message : 'Geocoding failed')
    } finally {
      setGeocoding(false)
    }
  }

  const coords = coordsFromValue(value)
  const mapLocations: MapLocation[] = coords
    ? [
        {
          id: 'address-preview',
          name: 'Service address',
          address: formatAddressLines(value),
          lat: coords.lat,
          lng: coords.lng,
          type: 'service-user',
        },
      ]
    : []

  const setField =
    (key: keyof AddressPlacesValue) =>
    (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
      onChange({ [key]: e.target.value })
    }

  return (
    <div className={cn('space-y-4', className)}>
      {configured ? (
        <div className="rounded-lg border border-sky-200/80 bg-sky-50/40 p-4 dark:border-sky-900 dark:bg-sky-950/20">
          <Label htmlFor="address-places-search" className="text-sm font-medium text-foreground">
            Search address
          </Label>
          <p className="mt-0.5 text-xs text-muted-foreground">
            Start typing to search with Google Places, then confirm on the map.
          </p>
          <div className="relative mt-2">
            <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              ref={searchRef}
              id="address-places-search"
              className="pl-9"
              placeholder="Search street address or postcode…"
              value={searchText}
              onChange={(e) => setSearchText(e.target.value)}
              disabled={disabled}
              autoComplete="off"
              data-testid="address-places-search"
            />
          </div>
          {!mapsReady && !mapsError ? (
            <p className="mt-2 flex items-center gap-2 text-xs text-muted-foreground">
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
              Loading address search…
            </p>
          ) : null}
          {mapsError ? <p className="mt-2 text-xs text-destructive">{mapsError}</p> : null}
          <div className="mt-3 flex flex-wrap gap-2">
            <Button
              type="button"
              variant="outline"
              size="sm"
              disabled={disabled || geocoding || !formatAddressLines(value).trim()}
              onClick={() => void geocodeCurrentAddress()}
            >
              {geocoding ? <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" /> : <MapPin className="mr-2 h-3.5 w-3.5" />}
              Show on map
            </Button>
            {coords ? (
              <Button
                type="button"
                variant="ghost"
                size="sm"
                disabled={disabled}
                onClick={() => setShowMap((v) => !v)}
              >
                {showMap ? 'Hide map' : 'View map'}
              </Button>
            ) : null}
          </div>
        </div>
      ) : (
        <div className="rounded-lg border border-dashed border-amber-300 bg-amber-50/80 px-4 py-3 text-sm text-amber-950 dark:border-amber-800 dark:bg-amber-950/30 dark:text-amber-100">
          Add <code className="rounded bg-muted px-1">VITE_GOOGLE_MAPS_API_KEY</code> to{' '}
          <code className="rounded bg-muted px-1">.env</code> and restart Vite for address search and map preview.
          You can still enter the address manually below.
        </div>
      )}

      {showMap && coords ? (
        <MapView locations={mapLocations} selectedId="address-preview" showList={false} height={280} />
      ) : null}

      <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
        <div className="md:col-span-2">
          <Label className="text-sm font-medium">Address line 1</Label>
          <Input
            data-testid="service-user-address-line1"
            className="mt-1.5"
            value={value.addressLine1}
            onChange={setField('addressLine1')}
            disabled={disabled}
            autoComplete="address-line1"
          />
        </div>
        <div className="md:col-span-2">
          <Label className="text-sm font-medium">Address line 2</Label>
          <Input
            className="mt-1.5"
            value={value.addressLine2}
            onChange={setField('addressLine2')}
            disabled={disabled}
            autoComplete="address-line2"
          />
        </div>
        <div>
          <Label className="text-sm font-medium">Town</Label>
          <Input
            data-testid="service-user-town"
            className="mt-1.5"
            value={value.town}
            onChange={setField('town')}
            disabled={disabled}
            autoComplete="address-level2"
          />
        </div>
