  "contents": "/** Google Maps JS API key from Vite env (Places + Geocoding). */
export function getGoogleMapsApiKey(): string | undefined {
  const raw = import.meta.env.VITE_GOOGLE_MAPS_API_KEY
  if (raw == null) return undefined
  const key = String(raw).trim()
  if (!key || key === 'undefined' || key === 'null') return undefined
  return key
}

export function isGoogleMapsConfigured(): boolean {
  return Boolean(getGoogleMapsApiKey())
}

export type GooglePlaceResult = {
  address_components?: GoogleAddressComponent[]
  formatted_address?: string
  geometry?: { location: { lat: () => number; lng: () => number } }
}

export type GoogleGeocodeResult = {
  address_components?: GoogleAddressComponent[]
  formatted_address?: string
  geometry: { location: { lat: () => number; lng: () => number } }
}

export type GoogleAddressComponent = {
  long_name: string
  short_name: string
  types: string[]
}

export type GooglePlacesAutocomplete = new (
  input: HTMLInputElement,
  opts?: {
    fields?: string[]
    types?: string[]
    componentRestrictions?: { country: string | string[] }
  },
) => {
  addListener: (event: string, handler: () => void) => void
  getPlace: () => GooglePlaceResult
}

export type GoogleGeocoder = new () => {
  geocode: (
    request: { address: string },
    callback: (results: GoogleGeocodeResult[] | null, status: string) => void,
  ) => void
}

type GoogleMapsCore = {
  maps: {
    importLibrary?: (name: string) => Promise<Record<string, unknown>>
    places?: { Autocomplete: GooglePlacesAutocomplete }
    Geocoder?: GoogleGeocoder
  }
}

declare global {
  interface Window {
    google?: GoogleMapsCore
  }
}

let scriptPromise: Promise<void> | null = null
let placesLibraryPromise: Promise<{ Autocomplete: GooglePlacesAutocomplete }> | null = null
let geocoderLibraryPromise: Promise<{ Geocoder: GoogleGeocoder }> | null = null

function rejectMissingKey(): never {
  throw new Error('VITE_GOOGLE_MAPS_API_KEY is not configured')
}

/** Load the Maps JS bootstrap script once. */
function loadGoogleMapsScript(): Promise<void> {
  const apiKey = getGoogleMapsApiKey()
  if (!apiKey) return Promise.reject(rejectMissingKey())

  if (window.google?.maps?.importLibrary || window.google?.maps?.places) {
    return Promise.resolve()
  }

  if (scriptPromise) return scriptPromise

  scriptPromise = new Promise((resolve, reject) => {
    const existing = document.querySelector<HTMLScriptElement>('script[data-google-maps-loader]')
    if (existing) {
      const done = () => {
        if (window.google?.maps) resolve()
        else reject(new Error('Google Maps failed to load'))
      }
      if (window.google?.maps) {
        done()
        return
      }
      existing.addEventListener('load', done, { once: true })
      existing.addEventListener('error', () => reject(new Error('Google Maps script failed')), { once: true })
      return
    }

    const script = document.createElement('script')
    script.dataset.googleMapsLoader = 'true'
    script.async = true
    script.defer = true
    // Async bootstrap — libraries are loaded via importLibrary(), not google.maps.places immediately.
    script.src = `https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(apiKey)}&loading=async`
    script.onload = () => {
      if (window.google?.maps) resolve()
      else reject(new Error('Google Maps failed to load'))
    }
    script.onerror = () => reject(new Error('Google Maps script failed'))
    document.head.appendChild(script)
  })

  return scriptPromise
}

async function importPlacesLibrary(): Promise<{ Autocomplete: GooglePlacesAutocomplete }> {
  await loadGoogleMapsScript()
  const maps = window.google?.maps
  if (!maps) throw new Error('Google Maps failed to load')

  if (typeof maps.importLibrary === 'function') {
    const lib = (await maps.importLibrary('places')) as { Autocomplete?: GooglePlacesAutocomplete }
    if (!lib.Autocomplete) {
      throw new Error(
        'Google Places library unavailable. Enable Places API (and Maps JavaScript API) for your API key.',
      )
    }
    return { Autocomplete: lib.Autocomplete }
  }

  // Legacy loader fallback (libraries=places in script URL)
  if (maps.places?.Autocomplete) {
    return { Autocomplete: maps.places.Autocomplete }
  }

  throw new Error(
    'Google Places library unavailable. Enable Places API (and Maps JavaScript API) for your API key.',
  )
}

async function importGeocodingLibrary(): Promise<{ Geocoder: GoogleGeocoder }> {
  await loadGoogleMapsScript()
  const maps = window.google?.maps
  if (!maps) throw new Error('Google Maps failed to load')

  if (typeof maps.importLibrary === 'function') {
    const lib = (await maps.importLibrary('geocoding')) as { Geocoder?: GoogleGeocoder }
    if (!lib.Geocoder) {
      throw new Error('Google Geocoding library unavailable.')
    }
    return { Geocoder: lib.Geocoder }
  }

  if (maps.Geocoder) {
    return { Geocoder: maps.Geocoder }
  }

  throw new Error('Google Geocoding library unavailable.')
}

/** Load Places Autocomplete (async bootstrap + importLibrary). */
export function loadGoogleMapsPlaces(): Promise<{ Autocomplete: GooglePlacesAutocomplete }> {
  if (!placesLibraryPromise) {
    placesLibraryPromise = importPlacesLibrary().catch((err) => {
      placesLibraryPromise = null
      throw err
    })
  }
  return placesLibraryPromise
}

/** Load Geocoder for address → coordinates. */
export function loadGoogleMapsGeocoder(): Promise<{ Geocoder: GoogleGeocoder }> {
  if (!geocoderLibraryPromise) {
    geocoderLibraryPromise = importGeocodingLibrary().catch((err) => {
      geocoderLibraryPromise = null
      throw err
    })
  }
  return geocoderLibraryPromise
}

/** @deprecated Use loadGoogleMapsPlaces() or loadGoogleMapsGeocoder() */
export function loadGoogleMaps(): Promise<GoogleMapsCore> {
  return loadGoogleMapsScript().then(() => {
    if (!window.google) throw new Error('Google Maps failed to load')
    return window.google
  })
}
