      setSearching(false)
      return
    }

    setSearching(true)
    setSearchError(null)
    const timer = window.setTimeout(() => {
      void searchPhotonAddresses(q, { countryRestriction, limit: 8 })
        .then((hits) => {
          setSuggestions(hits)
          setListOpen(hits.length > 0)
        })
        .catch((e: unknown) => {
          setSuggestions([])
          setSearchError(e instanceof Error ? e.message : 'Address search failed')
        })
        .finally(() => setSearching(false))
    }, 350)

