  "contents": "import type { AcceptedCarePlanItem } from '@/features/service-users/initial-assessment/api'
import { resolveEmployeeDisplayName } from '@/features/employees/lib/employee-display-name'
import { cn } from '@/shared/lib/utils'
import type { VisitPlanSlot } from '@/features/service-users/visit-plan/types'
import { normalizeTimeForInput } from '@/features/service-users/visit-plan/visit-plan-time.util'
import {
  formatMonthlyDays,
  formatVisitPlanFrequency,
  formatWeekdays,
} from '@/features/service-users/visit-plan/visit-plan-format'
import { resolveCarePlansForSlot } from '@/features/service-users/visit-plan/visit-plan-care-plan-links.util'

function DetailRow({
  label,
  value,
  className,
}: {
  label: string
  value: React.ReactNode
  className?: string
}) {
  return (
    <div className={cn('grid grid-cols-[minmax(0,7rem)_1fr] gap-x-3 gap-y-0.5 py-2 text-sm', className)}>
      <dt className="text-muted-foreground">{label}</dt>
      <dd className="min-w-0 break-words text-foreground">{value}</dd>
    </div>
  )
}

type Props = {
  slot: VisitPlanSlot
  acceptedCarePlans: AcceptedCarePlanItem[]
  employeeNameById: Map<string, string>
}

export function VisitPlanSlotCallPatternDetails({
  slot,
  acceptedCarePlans,
  employeeNameById,
}: Props) {
  const linkedPlans = resolveCarePlansForSlot(slot, acceptedCarePlans)
  const assignedNames = (slot.assignedEmployeeIds ?? []).map(id =>
    resolveEmployeeDisplayName(employeeNameById, id),
  )

  const scheduleDaysLabel =
    slot.scheduleFrequency === 'MONTHLY'
      ? formatMonthlyDays(slot)
      : slot.scheduleFrequency === 'WEEKLY' || slot.scheduleFrequency === 'DAILY'
        ? formatWeekdays(slot)
        : '—'

  return (
    <section className="rounded-lg border border-border bg-muted/10 p-4">
      <h4 className="mb-3 text-sm font-semibold text-foreground">Call pattern details</h4>
      <dl className="divide-y divide-border/60">
        <DetailRow label="Status" value={slot.isEnabled ? 'On' : 'Off'} />
        <DetailRow
          label="Visit window"
          value={`${normalizeTimeForInput(slot.plannedStartTime)} – ${normalizeTimeForInput(slot.plannedEndTime)}`}
        />
        <DetailRow label="Required carers" value={String(slot.requiredCarers)} />
        <DetailRow label="Frequency" value={formatVisitPlanFrequency(slot)} />
        <DetailRow label="Visit days" value={scheduleDaysLabel} />
        <DetailRow
          label="Care plans"
          value={
            linkedPlans.length === 0
              ? 'None linked'
              : linkedPlans.map(p => p.formName).join(', ')
          }
        />
        <DetailRow
          label="Assigned carers"
          value={assignedNames.length === 0 ? 'None assigned' : assignedNames.join(', ')}
        />
        {slot.medicationRoundCode ? (
          <DetailRow label="Time slot" value={slot.label || slot.medicationRoundCode} />
        ) : null}
      </dl>
      <p className="mt-3 text-xs text-muted-foreground">
        Times and carers are edited in the call pattern table. Scheduling frequency and visit-day rules
        are configured below.
      </p>
    </section>
  )
}
"
}

