  "contents": "import { cn } from '@/shared/lib/utils'
import type { VisitPlanSlot } from '@/features/service-users/visit-plan/types'
import { VISIT_PLAN_DAY_LABELS } from '@/features/service-users/visit-plan/types'
import { formatMonthlyDays, formatWeekdays } from '@/features/service-users/visit-plan/visit-plan-format'

const FREQUENCY_LABEL: Record<VisitPlanSlot['scheduleFrequency'], string> = {
  DAILY: 'Daily',
  WEEKLY: 'Weekly',
  MONTHLY: 'Monthly',
}

type Props = {
  slot: VisitPlanSlot
}

/** Read-only visit-day summary — days are edited in Scheduling & visit options only. */
export function VisitPlanSlotDaysCell({ slot }: Props) {
  if (!slot.isEnabled) {
    return <span className="text-xs text-muted-foreground">—</span>
  }

  const summary =
    slot.scheduleFrequency === 'MONTHLY' ? formatMonthlyDays(slot) : formatWeekdays(slot)

  return (
    <div className="min-w-[7.5rem] space-y-1.5" title="Edit visit days in Scheduling & visit options">
      <p className="text-[10px] font-medium uppercase tracking-wide text-muted-foreground">
        {FREQUENCY_LABEL[slot.scheduleFrequency]}
      </p>
      {slot.scheduleFrequency === 'MONTHLY' ? (
        <p className="text-xs text-foreground">{summary}</p>
      ) : (
        <div className="flex flex-wrap gap-0.5">
          {VISIT_PLAN_DAY_LABELS.map((label, dayIndex) => {
            const selected = slot.daysOfWeek.includes(dayIndex)
            return (
              <span
                key={label}
                className={cn(
                  'rounded px-1.5 py-0.5 text-[10px] font-medium',
                  selected
                    ? 'bg-teal-100 text-teal-900 dark:bg-teal-950 dark:text-teal-100'
                    : 'bg-muted/30 text-muted-foreground/50',
                )}
                aria-hidden
              >
                {label.slice(0, 3)}
              </span>
            )
          })}
        </div>
      )}
      {slot.scheduleFrequency !== 'MONTHLY' && slot.daysOfWeek.length === 0 ? (
        <p className="text-[10px] text-amber-700 dark:text-amber-300">No days selected</p>
      ) : null}
    </div>
  )
}
"
}

